module pci_genframe ( clk, reset, m_busreq, m_drdy, last_tx, lirdyno, 
        abort_timeout, gntni, framenid, irdynid, devselni, trdyni, stopni, 
        lframeno, ce_frameno, new_frameno );
  input clk, reset, m_busreq, m_drdy, last_tx, lirdyno, abort_timeout, gntni,
         framenid, irdynid, devselni, trdyni, stopni;
  output lframeno, ce_frameno, new_frameno;
