  GTECH_ONE U3 ( .Z(n10) );
  GTECH_AND2 U4 ( .A(n1), .B(n2), .Z(new_frameno) );
  GTECH_NOT U5 ( .A(lframeno), .Z(n2) );
  GTECH_OAI21 U6 ( .A(stopni), .B(n3), .C(n4), .Z(n1) );
  GTECH_AOI21 U7 ( .A(n5), .B(m_drdy), .C(abort_timeout), .Z(n4) );
