  GTECH_NOT U11 ( .A(reset), .Z(n9) );
  GTECH_NAND2 U12 ( .A(lframeno), .B(n7), .Z(ce_frameno) );
  GTECH_NAND3 U13 ( .A(m_busreq), .B(irdynid), .C(n8), .Z(n7) );
  GTECH_AND_NOT U14 ( .A(framenid), .B(gntni), .Z(n8) );
  GTECH_FJK3S lframeno_r_reg ( .J(n11), .K(n11), .TI(new_frameno), .TE(
        ce_frameno), .CP(clk), .CD(n10), .SD(n9), .Q(lframeno), .QN(n12) );
endmodule


